  FT["PH-H1276"] = {"id":"PH-H1276","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1442_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将西内格罗斯省比纳尔巴甘市镇索莱达村的名称变更为帕尧村的法案","en":"An Act Changing the Name of Barrio Soledad in the Municipality of Binalbagan, Province of Negros Occidental, to Barrio Payao","orig":"An Act Changing the Name of Barrio Soledad in the Municipality of Binalbagan, Province of Negros Occidental, to Barrio Payao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1442","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1442_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1276-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barrio Soledad in the Municipality of Binalbagan, Province of Negros Occidental, is hereby changed to Barrio Payao."}},{"id":"PH-H1276-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Barrio Soledad in the Municipality of Binalbagan, Province of Negros Occidental, to Barrio Payao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1277"] = {"id":"PH-H1277","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1443_1956.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Victorias Milling Co., Inc. 在菲律宾境内建设、维护和运营私人固定点对点、陆基与陆上移动无线电台的临时许可的法案","en":"An Act Granting the Victorias Milling Co., Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting the Victorias Milling Co., Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1443","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1443_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1277-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the Victorias Milling Co., Inc., its successors or assigns, a temporary permit to construct, maintain and operate in Victorias, Occidental Negros and at such places in the Philippines as the said company may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and land based and land mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1277-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of said stations be begun within two years from the date of the approval of this Act."}},{"id":"PH-H1277-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors, or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain, and operate private fixed point-to-point and land based and land mobile radio stations in such places within the Philippines as the interest of the trade and business of the grantee may justify."}},{"id":"PH-H1277-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H1277-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1277-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H1277-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H1277-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, is authorized to operate its private fixed point-to-point and land based and land mobile radio stations in the medium frequency, high frequency, and very high frequency that may be assigned to it by the Secretary of Public Works and Communications."}},{"id":"PH-H1277-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government upon just compensation."}},{"id":"PH-H1277-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H1277-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Victorias Milling Co., Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1278"] = {"id":"PH-H1278","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1444_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Ventura P. Marilao在莱特省Palompon市镇电灯、热力与动力系统特许经营权的法案","en":"An Act to Grant to Ventura P. Marilao a Franchise for an Electric Light, Heat and Power System in the Municipality of Palompon, Province of Leyte","orig":"An Act to Grant to Ventura P. Marilao a Franchise for an Electric Light, Heat and Power System in the Municipality of Palompon, Province of Leyte"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1444","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1444_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1278-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Ventura P. Marilao, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Palompon, Province of Leyte."}},{"id":"PH-H1278-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1278-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the plant and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1278-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Grant to Ventura P. Marilao a Franchise for an Electric Light, Heat and Power System in the Municipality of Palompon, Province of Leyte","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1279"] = {"id":"PH-H1279","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1445_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第526号共和国法（即《Cabanatuan市宪章》）若干条文的法案","en":"An Act Amending Certain Sections of Republic Act Numbered Five Hundred Twenty-Six, Otherwise Known as the Charter of the City of Cabanatuan","orig":"An Act Amending Certain Sections of Republic Act Numbered Five Hundred Twenty-Six, Otherwise Known as the Charter of the City of Cabanatuan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1445","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1445_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1279-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections two, seven, eight, eleven, seventy-five and eighty-nine of Republic Act Numbered Five hundred twenty-six, otherwise known as the Charter of the City of Cabanatuan, are amended to read as follows:\n\"Sec. 2 Territory of the City of Cabanatuan. — The City of Cabanatuan which is hereby created, shall comprise the present territorial jurisdiction of the Municipality of Cabanatuan, in the Province of Nueva Ecija. Within thirty days after the approval of this amendatory Act, the Municipal Board shall, with the approval of the proper Head of Department, divide the city into four districts which shall comprise, as far as practicable, contiguous and compact territory, with more or less the same area and population.\n\"The President of the Philippines may, by executive order, increase the territory of the City of Cabanatuan by adding thereto such contiguous barrios or municipalities as may be necessary and desirable in the public interest.\"\n\"Sec. 7 The Mayor—His election and compensation. -The Mayor shall be the chief executive of the city. He shall be elected by the qualified voters of the city during every election for provincial and municipal officials in conformity with the provisions of the Revised Election Code. No person shall be elected Mayor unless he is at least twenty-five years of age, is a qualified voter and has been a resident of the city for not less than one year prior to his election.\n\"He shall receive the salary provided for in Republic Act Numbered Eight hundred forty. With the approval of the proper Head of Department, the Mayor may be provided, in addition to his salary, a non-commutable allowance of not exceeding two thousand pesos per annum.\"\n\"Sec. 8 The Vice-Mayor. -There shall be a vice-mayor who shall perform the duties of the Mayor, in the event of the sickness, absence or other temporary incapacity of the Mayor, until said office shall be filled, in accordance with law. He shall be elected in the same manner and shall possess the same qualifications as the Mayor. He shall receive a salary of not more than three thousand six hundred pesos per annum. If, for any reason, the Vice-Mayor is temporarily incapacitated for the performance of the duties of the office of the Mayor, or said office of the Vice-Mayor is vacant, the duties of the Mayor shall be performed by the City Engineer. The Acting Mayor shall have the same powers and duties as the Mayor.\n\"The Vice-Mayor shall be the presiding officer of the Municipal Board and shall perform such other duties as may be assigned upon him by the Mayor or prescribed by law or ordinance.\"\n\"Sec. 11. Constitution and organization of the Municipal Board— compensation of members thereof. -The Municipal Board shall be the legislative body of the city and shall be composed of the Vice-Mayor, who shall be elected from each district by popular vote during every general election for provincial and municipal officials in conformity with the provisions of the Revised Election Code. In case of sickness, absence, suspension or other temporary disability of any member of the Board, or if necessary to maintain a quorum, the President of the Philippines may appoint a temporary substitute who shall possess all the rights and perform all the duties of a member of the Board until the return to duty of the regular incumbent.\n\"If any member of the Municipal Board should be candidate for office in any election, he shall be disqualified to act with the Board in the discharge of the duties conferred upon it relative to election matters, and in such case the other members of the Board shall discharge said duties without his assistance, or they may choose some disinterested elector of the city to act with the Board in such matters in his stead.\n\"The members of the Municipal Board shall receive ten pesos for each day of attendance of the session of the Board.\"\n\"Sec. 7 Regular, auxiliary and acting judges of municipal courts. -There shall be a municipal court for the City of Cabanatuan for which there shall be appointed two municipal judges and two auxiliary municipal judges.\n\"The municipal judge may, upon proper application, be allowed a vacation of not more than thirty days every year with salary. The auxiliary municipal judge shall discharge the duties in case of absence, incapacity or inability of the municipal judge until he resumes his post, or until a new judge shall have been appointed. During his incumbency the auxiliary municipal judge shall enjoy the powers, emoluments and privileges of the municipal judge who shall not receive any remuneration therefor except the salary to which he is entitled be reason of his vacation provided for in this Act.\n\"In case of absence, incapacity or inability, of both the municipal judge and the auxiliary municipal judge, the Secretary of Justice shall designate the justice of the peace of any of the adjoining municipalities to preside over the municipal court, and he shall hold the office temporarily until the regular incumbent or the auxiliary judge thereof shall have resumed office, or until another judge shall have been appointed in accordance with the provisions of this Act. The justice of the peace so designated shall receive his salary as justice of the peace plus seventy per cent of the salary of the municipal judge whose office he has temporarily assumed.\n\"The municipal judges shall receive a salary of not exceeding three thousand six hundred pesos per annum.\"\n\"Sec. 89. Election of provincial governor and members of the Provincial Board of the Province of Nueva Ecija. -The qualified voters of the city shall be eligible for the position, and be qualified and entitled to vote in the election, of the provincial governor and the members of the provincial board of the province of Nueva Ecija.\""}},{"id":"PH-H1279-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Certain Sections of Republic Act Numbered Five Hundred Twenty-Six, Otherwise Known as the Charter of the City of Cabanatuan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1280"] = {"id":"PH-H1280","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1446_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为菲律宾大学兽医学专业提供奖学金并为此拨款的法案","en":"An Act to Provide Scholarships for the Study of Veterinary Science in the University of the Philippines, Authorizing the Appropriation of Funds Therefor","orig":"An Act to Provide Scholarships for the Study of Veterinary Science in the University of the Philippines, Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1446","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1446_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1280-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Board of Regents of the University of the Philippines is hereby authorized to grant scholarships to Filipino citizens who desire to study in the College of Veterinary Science of the University of the Philippines: Provided, That there shall not be less than ten scholarships for the first year of the said college, and such scholarships shall be granted in accordance with the following principles:\n(a) The scholarships shall be granted only to bright and deserving students who shall be selected through competitive examinations;\n(b) The scholarships may include living expenses, traveling expenses, registration fees, matriculation fees and costs of books, instruments and other materials required in the study of veterinary science; and\n(c) The scholarships may be extended as an absolute grant to the scholar provided that he agrees to be employed in the government service for a certain number of years as may be determined by the Board of Regents; or it may be granted as a loan to be paid by the scholar out of his salary or earnings, without interest, after the scholarship is terminated. Payments collected on scholarships granted under this Act on a loan basis shall accrue to the Veterinary Science Scholarship Fund hereinafter constituted."}},{"id":"PH-H1280-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Board of Regents of the University of the Philippines shall promulgate such rules and regulations as may be necessary to carry into effect the provisions of this Act."}},{"id":"PH-H1280-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is authorized to be appropriated annually for a period of ten years, out of any funds in the National Treasury not otherwise appropriated, the sum of fifty thousand pesos to constitute the Veterinary Science Scholarship Fund and to carry into effect the purposes of this Act."}},{"id":"PH-H1280-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide Scholarships for the Study of Veterinary Science in the University of the Philippines, Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1281"] = {"id":"PH-H1281","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1447_1956.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 T.H. Valderrama and Sons 公司设立、维护和运营私人固定点对点无线电话站的临时许可法案","en":"An Act Granting T.H. Valderrama and Sons, Incorporated, a Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission and Reception of Wireless Messages to and from Said Stations","orig":"An Act Granting T.H. Valderrama and Sons, Incorporated, a Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission and Reception of Wireless Messages to and from Said Stations"},"level":"law","status":"active","topics":["company"],"docNumber":"Republic Act No. 1447","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1447_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1281-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"T.H. Valderrama and Sons, Incorporated, its successors or assigns, is hereby granted a temporary permit to establish, maintain and operate private fixed point-to-point radiotelephone stations in the City of Bacolod and in other parts of the Philippines where it operates and its lumber business, subject to the approval of the Secretary of Public Works and Communications, for transmission and reception of wireless messages to and from said stations, including its tugboats."}},{"id":"PH-H1281-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction, maintenance, and operation of said private fixed point-to-point radiotelephone stations on any land of the public domain upon such terms as he may prescribe."}},{"id":"PH-H1281-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The temporary permit granted under this Act shall continue to be in force while the Government has not established similar service at place hereinabove stated, and subject to the condition that the grantee, its successors or assigns, shall start operation under said permit within one and a half years from the date of the approval of this Act."}},{"id":"PH-H1281-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines, it being understood that the temporary permit under this Act merely secures the right of the grantee to establish, maintain, and operate private fixed point-to-point radiotelephone stations at the places hereinabove stated for no other purpose than to promote, protect, and subserve the trade and business interests of the grantee as a lumber company."}},{"id":"PH-H1281-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The actual operation of said private fixed point-to-point radiotelephone stations shall not commence until after the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder."}},{"id":"PH-H1281-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate such stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1281-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Republic of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radiotelephone stations."}},{"id":"PH-H1281-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or which may hereafter be enacted."}},{"id":"PH-H1281-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace and order to cause the closing of the grantee’s radiotelephone stations or to authorize the temporary use and operation thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1281-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The temporary permit granted under this Act shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant to the privilege herein provided for."}},{"id":"PH-H1281-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting T.H. Valderrama and Sons, Incorporated, a Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission and Reception of Wireless Messages to and from Said Stations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1282"] = {"id":"PH-H1282","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1448_1956.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Pepsi-Cola 菲律宾群岛装瓶公司运营私人固定点对点与基站无线电台以收发通信的临时许可的法案","en":"An Act Granting the Pepsi-Cola Bottling Company of the Philippine Islands, Inc. a Temporary Permit to Operate Private Fixed Point-to-Point and Private Base Radio Stations for the Reception and Transmission of Radio Communications to and from Said Stations","orig":"An Act Granting the Pepsi-Cola Bottling Company of the Philippine Islands, Inc. a Temporary Permit to Operate Private Fixed Point-to-Point and Private Base Radio Stations for the Reception and Transmission of Radio Communications to and from Said Stations"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1448","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1448_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1282-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to the Pepsi-Cola Bottling Company of the Philippine Islands, Inc., its successors or assigns, a temporary permit to construct, maintain and operate in the Philippines at such places as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and private base radio stations with corresponding land mobile units for the reception and transmission of wireless messages on radiotelephony or radiotelegraphy, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1282-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point and private base radio terms as he may prescribe."}},{"id":"PH-H1282-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of said stations be begun within one year from the date of the approval of this Act and be completed within two years from said date."}},{"id":"PH-H1282-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee, its successors, or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is merely to secure to the Pepsi-Cola Bottling Company of the Philippine Islands, Inc., the right to construct, maintain and operate private fixed point-to-point and private base radio stations in such places within the Philippines as the interests of the grantee may justify, for no other purpose than to protect, promote and subserve the trade and business interests of the grantee."}},{"id":"PH-H1282-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H1282-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1282-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H1282-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H1282-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder."}},{"id":"PH-H1282-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity, disaster, or disturbance of peace or order to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government, upon just compensation."}},{"id":"PH-H1282-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The temporary permit granted under this Act shall not be interpreted to mean an exclusive grant of the privilege herein provided for and is subject to amendment, alteration, or repeal by the Congress of the Philippines, when the public interest so requires."}},{"id":"PH-H1282-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Pepsi-Cola Bottling Company of the Philippine Islands, Inc. a Temporary Permit to Operate Private Fixed Point-to-Point and Private Base Radio Stations for the Reception and Transmission of Radio Communications to and from Said Stations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1283"] = {"id":"PH-H1283","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1449_1956.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 A. Soriano y Cia. 在菲律宾境内建设、维护和运营私人固定点对点、海岸、航空、陆基与陆上移动无线电台的临时许可的法案","en":"An Act Granting A. Soriano y Cia., a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point Coastal, Aeronautical, Land Based and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting A. Soriano y Cia., a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point Coastal, Aeronautical, Land Based and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1449","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1449_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1283-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to A. Soriano y Cia., successors or assigns, a temporary permit to construct, maintain and operate in such places in the Philippines where it operates its mining and other business, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point, coastal, aeronautical, land based and land mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1283-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, but in no case to go beyond July 4, 1974, and is granted upon the express condition that the same shall be void unless the construction or installation of said stations be begun within two years from the date of the approval of this Act and be completed within three years from said date."}},{"id":"PH-H1283-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors, or assigns, shall not engage in domestic business of telecommunications in the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain, and operate private fixed point-to-point, coastal, aeronautical, land based and land mobile radio stations at the places above-mentioned for no other purpose than to promote and protect the mining and other interests of the grantee."}},{"id":"PH-H1283-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H1283-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1283-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H1283-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, successors or assigns, shall be subject to the corporation laws of the Philippines now existing or which may hereafter be enacted."}},{"id":"PH-H1283-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, successors or assigns, is authorized to operate its private fixed point-to-point, coastal, aeronautical, land based and land mobile radio stations in the medium frequency, high frequency, and very high frequency that may be assigned to it by the Secretary of Public Works and Communications, or by any licensing authority."}},{"id":"PH-H1283-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government upon just compensation."}},{"id":"PH-H1283-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H1283-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting A. Soriano y Cia., a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point Coastal, Aeronautical, Land Based and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1284"] = {"id":"PH-H1284","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1450_1956.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Notre Dame 广播公司在哥打巴托省为宗教、教育与文化及商业目的建设、维护和运营无线电广播站的特许经营权法案","en":"An Act Granting the Notre Dame Broadcasting Corporation a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations in the Province of Cotabato for Religious, Educational and Cultural as Well as for Commercial Purposes","orig":"An Act Granting the Notre Dame Broadcasting Corporation a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations in the Province of Cotabato for Religious, Educational and Cultural as Well as for Commercial Purposes"},"level":"law","status":"active","topics":["investment","trade","education"],"docNumber":"Republic Act No. 1450","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1450_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1284-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, as well as of Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, not inconsistent with this Act, the Notre Dame Broadcasting Corporation is hereby granted a franchise to construct, maintain and operate for religious, educational and cultural as well as for commercial purposes and in the public interest, radio broadcasting stations in the Province of Cotabato."}},{"id":"PH-H1284-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period twenty-five years from the date the said stations shall be put in operation, and is granted upon the express condition that the same shall be void unless the construction of at least one station be begun within one year from the date of approval of this Act and be completed within two years from the said date."}},{"id":"PH-H1284-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise is likewise made upon the express condition that the grantee shall provide adequate public service time to enable the Government, thru its stations, to reach the population on important issues, shall assist in the functions of public information and education, shall conform to the ethics of honest enterprise, and shall not use its stations for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H1284-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee’s radio broadcasting stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequency and wave lengths to be used under this franchise and issued to the grantee license for such use."}},{"id":"PH-H1284-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The radio broadcasting stations of the grantee shall be so constructed and operated and the wave lengths so selected as to avoid interference with existing radio stations and to permit of the expansion of the grantee’s services."}},{"id":"PH-H1284-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the Government without compensating the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H1284-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall be liable to pay the same taxes, unless exempted therefrom, on its real estate, buildings, and personal property, exclusive of the franchise, as other persons or corporation are now or hereafter may be required by law to pay. It shall be liable further to pay all other taxes as provided in the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H1284-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H1284-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Acceptance of this franchise shall be given in writing by the grantee within six months after the approval of this Act. When so accepted, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H1284-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall file a bond in the amount of five thousand pesos to guarantee the full compliance with and fulfillment of the conditions under which this franchise is granted. If after two years from the date of acceptance of this franchise, the grantee shall have fulfilled said conditions or soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H1284-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play or other matter to be broadcast from its stations; but if any such speech, play or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play or other matter: Provided, That the grantee, during any broadcast may cut off from the air and speech, play or other matter being broadcast if the tendency is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral."}},{"id":"PH-H1284-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred, or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, or corporation or other commercial or legal entity."}},{"id":"PH-H1284-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This franchise shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1284-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Notre Dame Broadcasting Corporation a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations in the Province of Cotabato for Religious, Educational and Cultural as Well as for Commercial Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1285"] = {"id":"PH-H1285","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1451_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第328号共和国法第86条（即Calbayog市 Charter）的法案","en":"An Act Amending Section Eighty-Six of Republic Act Numbered Three Hundred Twenty-Eight, Otherwise Known as the Charter of the City of Calbayog","orig":"An Act Amending Section Eighty-Six of Republic Act Numbered Three Hundred Twenty-Eight, Otherwise Known as the Charter of the City of Calbayog"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1451","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1451_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1285-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eighty-six of Republic Act Numbered Three hundred twenty-eight, otherwise known as the Charter of the City of Calbayog, is hereby amended to read as follows:\n\"Sec. 86. The Bureau of Public Schools. -The Director of Public Schools shall exercise the same jurisdiction and powers in the city as elsewhere in the Philippines and the Division Superintendent of Schools for the Province of Samar, shall act as ex officio City Superintendent of Schools of the City of Calbayog with additional compensation at the rate of eight hundred pesos per annum payable from the funds of the city. He shall have all the powers and duties in respect to the schools of the city as are vested in the division superintendents in respect to schools of their division.\""}},{"id":"PH-H1285-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect on July one, nineteen hundred fifty-two.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Section Eighty-Six of Republic Act Numbered Three Hundred Twenty-Eight, Otherwise Known as the Charter of the City of Calbayog","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1286"] = {"id":"PH-H1286","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1452_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1200号共和国法第一编B部分第一目al项第10分项（即《为公共工程拨款并修订第920号共和国法》）的法案","en":"An Act Amending Sub-Item Ten of Item al, Subsection One, Title B of Section One, Republic Act Numbered Twelve Hundred, Entitled “An Act Appropriating Funds for Public Works and Amending Republic Act Numbered Nine Hundred and Twenty”","orig":"An Act Amending Sub-Item Ten of Item al, Subsection One, Title B of Section One, Republic Act Numbered Twelve Hundred, Entitled “An Act Appropriating Funds for Public Works and Amending Republic Act Numbered Nine Hundred and Twenty”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1452","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1452_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1286-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sub-item ten of item al, subsection one, Title B of section one, Republic Act Numbered Twelve hundred, is hereby amended to read as follows:\n\"(10) Asphalt paving of the following streets, Municipality of Balawan, Negros Oriental: Buenavista Street from Zamora Street to Mabini Street; Mabini Street from Progreso Street to Burgos Street; Burgos Street from Mabini Street to General Luna Street; General Luna Street from Burgos Street to Nueva Street; Independence Street from provincial road to Nueva Street; La Libertad Street from provincial road to Rizal Street; Martires Street from provincial road to Progreso Street; Progreso Street from General Luna Street to Martires Street; Rizal Street from General Luna Street to La Libertad Street; Nueva Street from General Luna Street to Independence Street ₱15,000.00\""}},{"id":"PH-H1286-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Sub-Item Ten of Item al, Subsection One, Title B of Section One, Republic Act Numbered Twelve Hundred, Entitled “An Act Appropriating Funds for Public Works and Amending Republic Act Numbered Nine Hundred and Twenty”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1287"] = {"id":"PH-H1287","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1453_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"授予A.S. Diaz Electric Service在巴科洛德市及其郊区安装、运营与维护电灯、热力与动力系统的特许经营权的法案","en":"An Act Granting A.S. Diaz Electric Service a Franchise to Install, Operate, and Maintain an Electric Light, Heat, and Power System in the City of Bacolod and its Suburbs","orig":"An Act Granting A.S. Diaz Electric Service a Franchise to Install, Operate, and Maintain an Electric Light, Heat, and Power System in the City of Bacolod and its Suburbs"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1453","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1453_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1287-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, there is granted to A.S. Diaz Electric Service, for a period of fifty years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the City of Bacolod and its suburbs."}},{"id":"PH-H1287-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1287-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In consideration of the franchise and rights hereby granted, the grantee shall pay into the treasury of the Philippines a franchise tax equal to two per centum of the gross earnings for electric current sold under this franchise.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting A.S. Diaz Electric Service a Franchise to Install, Operate, and Maintain an Electric Light, Heat, and Power System in the City of Bacolod and its Suburbs","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1288"] = {"id":"PH-H1288","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1454_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第1200号共和国法若干条款的法案","en":"An Act to Amend Certain Provisions of Republic Act Numbered Twelve Hundred","orig":"An Act to Amend Certain Provisions of Republic Act Numbered Twelve Hundred"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1454","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1454_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1288-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item (one), paragraph \"bq\" for the City of Manila, section two of Republic Act Numbered Twelve hundred, is amended to read as follows:\n\"(1) Construction of sixteen-room concrete administration building with office and (one) library, Torres High School (1st district) ₱200,000.00\""}},{"id":"PH-H1288-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Item (two), paragraph \"bq\" for the City of Manila of section two of the same Act is repealed."}},{"id":"PH-H1288-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Provisions of Republic Act Numbered Twelve Hundred","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1289"] = {"id":"PH-H1289","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1455_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1411号共和国法G编附录A中项目的编号与地点的法案","en":"An Act Amending the Project Number and Location of the Project in Appendix A, Title G, of Republic Act Numbered Fourteen Hundred Eleven","orig":"An Act Amending the Project Number and Location of the Project in Appendix A, Title G, of Republic Act Numbered Fourteen Hundred Eleven"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1455","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1455_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1289-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The project number and location of the project for Project Numbered G-05.10 in Appendix A, Title G, of Republic Act Numbered Fourteen hundred eleven, is hereby amended to read as follows:\n\"G-32.1: Camalig-Catmon Irrigation Project, Albay.\""}},{"id":"PH-H1289-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending the Project Number and Location of the Project in Appendix A, Title G, of Republic Act Numbered Fourteen Hundred Eleven","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1290"] = {"id":"PH-H1290","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1456_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订第980号共和国法（即授予菲律宾Lyceum在马尼拉建设、维护与运营无线电广播站特许权之法）的法案","en":"An Act to Amend Republic Act Numbered Nine Hundred Eighty Which Grants to the Lyceum of the Philippines a Franchise to Construct, Maintain and Operate a Radio Broadcasting Station in Manila","orig":"An Act to Amend Republic Act Numbered Nine Hundred Eighty Which Grants to the Lyceum of the Philippines a Franchise to Construct, Maintain and Operate a Radio Broadcasting Station in Manila"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1456","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1456_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1290-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 1 of Republic Act Numbered Nine hundred eighty is amended to read as follows:\n\"Sec. 1. Subject to the provisions of the Constitution, as well as of Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws not inconsistent with this Act, the Lyceum of the Philippines is hereby granted a franchise to construct, maintain and operate, for educational and commercial purposes and in the public interest, a radio broadcasting station in the City of Manila.\""}},{"id":"PH-H1290-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section seven of the same Act is amended to read as follows:\n\"Sec. 7. (a) The grantee shall be liable to pay the same taxes, unless exempted therefrom, on its real estate, buildings, and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay.\n\"(b) The grantee shall further be liable to pay all other taxes as provided in the National Internal Revenue Code by reason of this franchise.\""}},{"id":"PH-H1290-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The same Act is further amended by inserting between sections nine and ten thereof two new sections to be known as sections nine-a and nine-b which shall read as follows:\n\"Sec. 9-A. The grantee shall execute a bond in favor of the Government of the Philippines in the sum of twenty thousand pesos to guaranty for the faithful compliance and fulfillment of the grantee’s obligations hereunder during the first three years of the life of this franchise. If, after three years from the date of the acceptance of this franchise, the grantee shall fulfill said obligations, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications.\n\"Sec. 9-B. The grantee shall not require any previous censorship of any speech, play, or other matter to be broadcast from its station; but if any such speech, play, or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, or other matter: Provided, That the grantee, during any broadcast, may cut off from the air the speech, play, or other matter being broadcast if the tendency thereof is to propose and or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral.\""}},{"id":"PH-H1290-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Nine Hundred Eighty Which Grants to the Lyceum of the Philippines a Franchise to Construct, Maintain and Operate a Radio Broadcasting Station in Manila","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1291"] = {"id":"PH-H1291","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1457_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1411号共和国法第3条，规定在奎松省 Quezon 市镇建造车间大楼的法案","en":"An Act to Amend Section Three of Republic Act Numbered One Thousand Four Hundred Eleven to Provide for the Construction of a Shop Building in the Municipality of Quezon, Province of Quezon","orig":"An Act to Amend Section Three of Republic Act Numbered One Thousand Four Hundred Eleven to Provide for the Construction of a Shop Building in the Municipality of Quezon, Province of Quezon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1457","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1457_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1291-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item fifty-one, roman numbered two, subsection aq. Quezon, section three of Republic Act Numbered One thousand four hundred eleven, is hereby amended to read as follows:\n51. Quezon Central School Shop Building—Construction ₱3,000.00\""}},{"id":"PH-H1291-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section Three of Republic Act Numbered One Thousand Four Hundred Eleven to Provide for the Construction of a Shop Building in the Municipality of Quezon, Province of Quezon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
