  FT["PH-H1294"] = {"id":"PH-H1294","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1460_1956.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"修订第 183 号共和国法（即经修正的《帕赛市宪章》）若干条的法案","en":"An Act to Amend Certain Sections of Republic Act Numbered One Hundred Eighty-Three Otherwise Known as the Charter of Pasay City, as Amended","orig":"An Act to Amend Certain Sections of Republic Act Numbered One Hundred Eighty-Three Otherwise Known as the Charter of Pasay City, as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1460","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1460_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1294-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The second paragraph of section seven of Republic Act Numbered One hundred eighty-three is hereby amended to read as follows:\n\"He shall receive a salary of eight thousand four hundred pesos a year.\""}},{"id":"PH-H1294-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first paragraph of section twenty-two of Republic Act Numbered One hundred eighty-three is hereby amended to read as follows:\n\"Sec. 22. The City Treasurer— His powers, duties and compensation. -There shall be a city treasurer who shall have charge of the department of finance and shall act as chief fiscal officer and financial adviser of the city and custodian of its funds. He shall receive a salary of seven thousand two hundred pesos per annum. He shall have the following general powers and duties:\""}},{"id":"PH-H1294-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first paragraph of section twenty-three of Republic Act Numbered One hundred eighty-three is hereby amended to read as follows:\n\"Sec. 23. The City Engineer— His powers, duties and compensation. -There shall be a city engineer, who shall be in charge of the department of engineering and public works. He shall receive a salary of seven thousand two hundred pesos per annum. He shall have the following powers and duties:\""}},{"id":"PH-H1294-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section twenty-six of Republic Act Numbered One hundred eighty-three is amended to read as follows:\n\"Sec. 26. Compensation of City Attorney and his Assistants. -The city attorney and his assistants shall receive the salaries hereinafter set forth, which shall be paid by Pasay City:\n\"(a) City attorney, not exceeding seven thousand two hundred pesos per annum.\n\"(b) First assistant city attorney, not exceeding six thousand six hundred pesos per annum.\n\"(c) Second assistant city attorney, not exceeding six thousand pesos per annum.\n\"(d) Two third assistant city attorneys, not exceeding five thousand four hundred pesos each per annum.\n\"(e) Two fourth assistant city attorneys, not exceeding four thousand eight hundred pesos each per annum.\""}},{"id":"PH-H1294-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Sections of Republic Act Numbered One Hundred Eighty-Three Otherwise Known as the Charter of Pasay City, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
