  FT["PH-H1309"] = {"id":"PH-H1309","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1475_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1200号共和国法第1条F目的法案","en":"An Act Amending Title F of Section One of Republic Act Numbered One Thousand Two Hundred","orig":"An Act Amending Title F of Section One of Republic Act Numbered One Thousand Two Hundred"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1475","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1475_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1309-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title F of section one of Republic Act numbered One thousand two hundred is hereby amended by transferring sub-item H (5) of item \"af. Negros Occidental\" to item \"n. Capiz\" as sub-item (4) thereof."}},{"id":"PH-H1309-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Title F of Section One of Republic Act Numbered One Thousand Two Hundred","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1310"] = {"id":"PH-H1310","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1476_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"废止第466号联邦法（经修正）第296条、第297条、第298条、第299条与第300条的法案","en":"An Act Repealing Sections Two Hundred Ninety-Six, Two Hundred Ninety-Seven, Two Hundred Ninety-Eight, Two Hundred Ninety-Nine, and Three Hundred of Commonwealth Act Numbered Four Hundred Sixty-Six, as Amended","orig":"An Act Repealing Sections Two Hundred Ninety-Six, Two Hundred Ninety-Seven, Two Hundred Ninety-Eight, Two Hundred Ninety-Nine, and Three Hundred of Commonwealth Act Numbered Four Hundred Sixty-Six, as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1476","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1476_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1310-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections two hundred ninety-six, two hundred ninety-seven, two hundred ninety-eight, two hundred ninety-nine and three hundred, Chapter Eight, of Commonwealth Act Numbered Four hundred sixty-six, as amended, are hereby repealed: Provided, That all fees heretofore collected under the above-named sections of Commonwealth Act Numbered Four hundred sixty-six, as amended, shall continue to be disbursed in accordance with the provisions of the said Act."}},{"id":"PH-H1310-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All fees uncollected under the above-specified provisions of said Act are hereby condoned."}},{"id":"PH-H1310-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Repealing Sections Two Hundred Ninety-Six, Two Hundred Ninety-Seven, Two Hundred Ninety-Eight, Two Hundred Ninety-Nine, and Three Hundred of Commonwealth Act Numbered Four Hundred Sixty-Six, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1311"] = {"id":"PH-H1311","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1477_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第53号共和国法第1条（即《豁免任何出版物的出版人、编辑、专栏作家或记者披露已发表新闻来源或保密获得信息》）的法案","en":"An Act Amending Section One of Republic Act Numbered Fifty-Three, Entitled “An Act to Exempt the Publisher, Editor, Columnist or Reporter of Any Publication from Revealing the Source of Published News or Information Obtained in Confidence”","orig":"An Act Amending Section One of Republic Act Numbered Fifty-Three, Entitled “An Act to Exempt the Publisher, Editor, Columnist or Reporter of Any Publication from Revealing the Source of Published News or Information Obtained in Confidence”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1477","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1477_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1311-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Fifty-three is amended to read as follows:\n\"Sec. 1. Without prejudice to his liability under the civil and criminal laws, the publisher, editor, columnist or duly accredited reporter of any newspaper, magazine or periodical of general circulation cannot be compelled to reveal the source of any news-report or information appearing in said publication which was related in confidence to such publisher, editor or reporter unless the court or a House or committee of Congress finds that such revelation is demanded by the security of the State.\""}},{"id":"PH-H1311-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Section One of Republic Act Numbered Fifty-Three, Entitled “An Act to Exempt the Publisher, Editor, Columnist or Reporter of Any Publication from Revealing the Source of Published News or Information Obtained in Confidence”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1312"] = {"id":"PH-H1312","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1478_1956.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"设立旅游与观光业委员会、界定其权力、职责并为其他目的法案","en":"An Act to Create a Board of Travel and Tourist Industry, Defining its Powers, Duties and Responsibilities, and for Other Purposes","orig":"An Act to Create a Board of Travel and Tourist Industry, Defining its Powers, Duties and Responsibilities, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1478","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-15","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1478_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1312-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a Board of Travel and Tourist Industry to regulate international travel and tourism with a view to the development of a prosperous Philippine tourist industry. The Board shall be composed of the Secretary of Commerce as Chairman and the under secretaries of Foreign Affairs, Finance, Justice and Public Works and Communications, the President of the Philippines Chamber of Commerce and the President of the Philippine Tourist and Travel Association, as members."}},{"id":"PH-H1312-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Board shall have the following responsibilities and duties:\n(a) It shall coordinate the activities of all agencies of the government which concern international travel and tourism;\n(b) It shall promote the removal of unnecessary barriers to travel and the integration and simplification of travel regulations and requirements as well as their efficient, fair and courteous enforcement to assure expeditious, pleasant and hospitable reception of all tourists and visitors and utmost satisfaction on their part during their stay in the country and upon their departure;\n(c) It shall undertake the development of tourist attractions and provide and maintain essential facilities for tourists and travelers where private enterprise is not prepared to take care of them;\n(d) It shall organize and support a program of promotion and publicity calculated to interest, attract and induce people abroad to visit the Philippines and patronize things Philippine and to enhance the prestige of the Filipino people and the Republic;\n(e) It shall regulate and license the business of travel agents; and\n(f) It shall exercise supervision over the operation of all facilities and services that cater to or have anything to do with foreign travelers and tourists with a view to insuring the maintenance of the highest possible standards, reasonable charges, courtesy, honesty and efficiency."}},{"id":"PH-H1312-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"To carry out the aims and purposes of this Act, a tax shall be collected on all fares of passengers leaving the country as well as fares for those returning or coming in, if payable here, at the following rates:\n(a) If said passage costs not more than sixty pesos, seven pesos and fifty centavos.\n(b) If said passage costs not more than sixty pesos and not more than one hundred twenty pesos, twelve pesos.\n(c) If said passage costs more than one hundred twenty pesos and not more than two hundred and fifty pesos, fifteen pesos.\n(d) If said passage costs more than two hundred and fifty pesos and not more than five hundred pesos, thirty pesos.\n(e) If said passage costs more than five hundred pesos, and not more than one thousand pesos, fifty pesos.\n(f) If said passage costs more than one thousand pesos, one hundred pesos.\nSection two hundred and twenty-eight of Commonwealth Act Numbered Four hundred and sixty-six, as amended, is repealed."}},{"id":"PH-H1312-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This tax shall be collected from the passengers by the carriers and travel agencies issuing foreign travel passenger tickets and they, in turn, shall remit their collections within the first ten days of every succeeding quarter to the Board of Travel and Tourist Industry."}},{"id":"PH-H1312-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"An amount not in excess of 50 per cent of such collections and all those which may be effected under section six shall accrue to the funds of the Board to be spent under its authority exclusively for the development of tourist facilities and the promotion of tourism both within the country and abroad, through all well-known media but especially through foreign publicity and advertising. The other fifty per cent shall accrue to the general funds of the Government and shall be accounted for and delivered by the Board of Travel and Tourist Industry to the Treasurer of the Philippines."}},{"id":"PH-H1312-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Board shall regulate travel agency business, prescribing the necessary rules to be govern their establishment and operation. It shall fix and collect an annual license fee from every individual or group engaged in the travel agency business in an amount not in excess of one hundred pesos a year. No individual or firm shall engage in the travel agency business without being licensed by the Board of Travel and Tourist Industry."}},{"id":"PH-H1312-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the exercise of its supervisory powers over facilities and services catering to or having anything to do with foreign travelers and tourists, the Board shall prescribe rules and regulations for their operation and maintenance. In case of non-compliance with such rules and regulations, it shall take the necessary steps to cancel or recommend the cancellation of the permits of the offending parties or their prosecution, if warranted."}},{"id":"PH-H1312-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"For the purpose of strengthening the competitive position of the Philippines in the field of international tourism, the President of the Philippines, upon recommendation of the Board, may:\n(a) Suspend the payment of visa and visa application fees for foreign tourists and travelers coming to the Philippines;\n(b) Exempt foreign tourists and travelers from payment of taxes on food, drinks, cigars and cigarettes consumed by them, as well as amusement taxes during their stay in the country;\n(c) Allow foreign visitors and travelers leaving the country to carry with them or have mailed or shipped for them within sixty days of their departure, free of export licenses, taxes or fees, any quantity of locally purchased Philippine souvenir or gift goods when the value thereof shall not exceed one thousand pesos;\n(d) Transfer to the Board the control and supervision of any such facilities, services, rights and properties, real or personal, as may now be owned, operated or maintained by other government agencies or instrumentalities which may be helpful in the effective promotion and development of the tourist industry."}},{"id":"PH-H1312-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Philippine Tourist and Travel Association, Inc., which under its charter, Republic Act Numbered Seven hundred and ten is the exclusive agency of the government in the promotion of the tourist industry, shall be the instrumentality of the Board in carrying out the objectives of this Act."}},{"id":"PH-H1312-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Board shall pass upon the requirements of the said Association and make available out of its revenues as provided for in sections five and six above such sums may be necessary for carrying out its program of activities."}},{"id":"PH-H1312-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The Board of Travel and Tourist Industry shall, five days before the opening of the regular sessions of Congress, submit to Congress a verified detailed report of its collections, disbursements, and activities including those of the Philippine Tourist and Travel Association, Inc. and of its accomplishments and a copy of the plantilla as of December thirty-first of the year immediately preceding."}},{"id":"PH-H1312-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"All provisions of law contrary to the provisions of this Act or are inconsistent with its aims and objectives are hereby repealed."}},{"id":"PH-H1312-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1956"}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Create a Board of Travel and Tourist Industry, Defining its Powers, Duties and Responsibilities, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1313"] = {"id":"PH-H1313","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1479_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"对《国家国内税收法典》的修改","en":"An Act to Amend Section One Hundred and Thirty-Seven of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code","orig":"An Act to Amend Section One Hundred and Thirty-Seven of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1479","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1479_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1313-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one hundred and thirty-seven of Commonwealth Act Numbered Four hundred and sixty-six, as last amended by Republic Act Numbered Eight hundred and eighteen, is hereby further amended to read as follows:\n\"Sec. 137. Specific tax on cigars and cigarettes. — On cigars and cigarettes there shall be collected the following taxes:\n\"(a) Cigars— \"(1) When the manufacturer’s or importer’s wholesale price, less the amount of the tax, does not exceed thirty pesos per thousand, on each thousand, two pesos and thirty centavos.\n\"(2) When the manufacturer’s or importer’s wholesale price, less the amount of the tax, exceeds thirty pesos but does not exceed sixty pesos per thousand, on each thousand, four pesos and sixty centavos.\n\"(3) When the manufacturer’s or importer’s wholesale price, less the amount of the tax, exceeds sixty pesos per thousand, on each thousand, seven pesos.\n\"(b) Cigarettes— \"(1) On cigarettes containing Virginia type tobacco and/or flue-cured tobacco of seventy-one millimeters or less in length weighing one and one-fourth kilos or less per thousand, not wrapped in tinfoil or cellophane or packed in cartons or in tin cans, on each thousand, eight pesos: Provided, That if the length exceeds seventy-one millimeters or if the weight per thousand exceeds one and one-fourth kilos, the tax shall be increased by one hundred per centum.\n\"(2) On cigarettes containing Virginia type tobacco and/or flue-cured tobacco of seventy-one millimeters or less in length weighing one and one-fourth kilos or less per thousand, wrapped in tinfoil or cellophane or packed in cartons covered with paraffin or wax paper or in tin cans, on each thousand, twelve pesos: Provided, That if the length exceeds seventy-one millimeters or if the weight per thousand exceeds one and one-fourth kilos, the tax shall be increased by one hundred per centum.\n\"(3) On cigarettes made of leaf tobacco other than Virginia type tobacco and/or flue-cured tobacco of eighty-one millimeters or less in length weighing one and three-fourth kilos or less per thousand, on each thousand, two pesos and fifty centavos: Provided, That if the length exceeds eighty-one millimeters, or the weight per thousand exceeds one and three-fourth kilos, the tax shall be increased by fifty per centum: Provided, further, That if the length exceeds one hundred twenty-one millimeters, on each thousand the tax shall be increased by one hundred per centum.\n\"(4) If the cigarettes taxable under subparagraphs (1), (2) and (3) hereof are mechanically wrapped or packed, the tax shall be increased by one hundred and twenty per centum per thousand cigarettes.\n\"Cigarettes shall be considered as mechanically wrapped or packed when at any stage of the wrapping or packing, a machine or any mechanical contrivance shall have been used.\n\"The maximum price at which the various classes of cigars are sold at wholesale in the factory or in the establishment of the importer to the public shall determine the rate of the tax applicable to such cigars; and if the manufacturer or importer also sells, or allows to be sold, his cigars at wholesale in another establishment of which he is the owner or in the profits of which he has an interest, the maximum sale price in such establishment shall determine the rate of the tax applicable to the cigars therein sold: Provided, However , That when such maximum wholesale price is less than the cost of manufacture or importations plus all expenses incurred until the cigars are finally sold by the manufacturer or importer, such cost plus expenses shall determine the amount of tax to be applied.\n\"Every manufacturer or importer of cigars shall file with the Collector of Internal Revenue, on the date or dates designated by the latter, a sworn statement showing the maximum wholesale prices of cigars, together with the cost of manufacture or importation plus expenses incurred or to be incurred until the cigars are finally sold and it shall be unlawful to sell said cigars at wholesale at a price in excess of the one specified in the statement required by this Title without previous written notice to said Collector of Internal Revenue. In the case of imported cigars, the sworn statement required herein shall be accompanied by verified sales invoices of the manufacturers of the cigars as well as the consular invoice issued by a Philippine Consul, should one be available at the place of origin or shipment.\n\"Every manufacturer or importer of cigarettes shall file with the Collector of Internal Revenue, on the date or dates designated by the latter, a sworn statement showing the brand or brands of cigarettes manufactured or imported, their corresponding length in millimeters and weight in kilos per thousand cigarettes, whether containing flue-cured tobacco, wrapped in cellophane or tinfoil, or packed in cartons with paraffin or wax paper, or in tin cans, and whether the cigarettes are mechanically wrapped or packed. In the case of imported cigarettes, the sworn statement required herein shall, in addition to the above information, be accompanied by a verified commercial invoice of the manufacturer of the cigarettes as well as the consular invoice issued by a Philippine Consul, if any, containing the information that Philippine internal revenue strip stamps have been affixed to each and every pack of cigarettes and that each pack bears the inscription \"For export to the Philippines\".\n\"If the government of a foreign country permits the revenue stamps of such country to be affixed in the Philippines to tobacco (including cigars) or snuff manufactured in the Philippines and imported into such foreign country internal revenue stamps of the Philippines may be affixed to tobacco (including cigars) or snuff manufactured in such foreign country, under such rules and regulations as the Collector of Internal Revenue with the approval of the Secretary of Finance may prescribe.\""}},{"id":"PH-H1313-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1956."}}],"pack":"ph-p18"};
  FT["PH-H1314"] = {"id":"PH-H1314","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1480_1956.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"授权复兴金融公司与菲律宾国家银行向菲律宾贸易、农业与技术院校毕业的菲律宾公民提供贷款","en":"An Act Authorizing the Rehabilitation Finance Corporation and the Philippine National Bank to Grant Loans to Graduates of Trade, Agricultural and Technical Schools and Colleges in the Philippines Who are Filipino Citizens","orig":"An Act Authorizing the Rehabilitation Finance Corporation and the Philippine National Bank to Grant Loans to Graduates of Trade, Agricultural and Technical Schools and Colleges in the Philippines Who are Filipino Citizens"},"level":"law","status":"active","topics":["company","trade","tax"],"docNumber":"Republic Act No. 1480","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-15","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1480_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1314-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is hereby declared a national policy to give financial assistance to graduates of trade, technical and agricultural schools and colleges with a view to helping them start an industry, own a shop or develop a farm and thus help solve the unemployment problem, and hasten the economic development of the Philippines."}},{"id":"PH-H1314-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In accordance with this policy, any provision of law or regulation to the contrary notwithstanding, the Rehabilitation Finance Corporation and the Philippine National Bank are authorized to grant to any bona fide graduate of a government trade or technical school or college or a trade or technical school or college duly recognized by the Government, a loan of not exceeding two thousand, pesos, and to bona fide graduates of a government agricultural school or college or a private agricultural school or college duly recognized by the government a loan of not exceeding three thousand pesos with the collateral of the property purchased with the amount borrowed as hereinafter authorized and payable in five years with interest at the rate of four per centum to be used by said graduate for the purchase of necessary equipment and/or the establishment of his shop to be operated by him or the purchase of necessary agricultural implements or seeds for the development of said land: Provided, however , That the said loan shall be guaranteed by two solvent and of good standing citizens of the Philippines who are not constitutional officers: Provided, further , That applications for loans under this Act shall be given preference over applications for loans of twenty thousand pesos or more : Provided , finally , That as far as practicable, loans shall be equitably granted to secure a nationwide distribution and coverage and prevent an undue concentration of loan grants in any one place."}},{"id":"PH-H1314-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It shall be unlawful for any person who receives a loan under the provision of this Act to use the said loan or any part thereof for purposes other than those mentioned in section two hereof."}},{"id":"PH-H1314-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Any person who shall violate the provisions of section three of this Act shall be punished with imprisonment of not less than six months nor more than one year, and in addition the loan so obtained will immediately be due and demandable."}},{"id":"PH-H1314-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Only Filipino citizens shall avail themselves of this Act."}},{"id":"PH-H1314-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956"}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Rehabilitation Finance Corporation and the Philippine National Bank to Grant Loans to Graduates of Trade, Agricultural and Technical Schools and Colleges in the Philippines Who are Filipino Citizens","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1315"] = {"id":"PH-H1315","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1481_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"对《保险法》的修改","en":"An Act to Amend Act Numbered Two Thousand Four Hundred and Twenty-Seven, Otherwise Known as the Insurance Act, as Amended, by Adding After Section One Hundred Sixty-Four Thereof, Section One Hundred Sixty-Four-A, Making Obligatory the Insertion in the Policy of Fire Insurance a Clause on Prima Facie Evidence of Arson, and for Other Purposes","orig":"An Act to Amend Act Numbered Two Thousand Four Hundred and Twenty-Seven, Otherwise Known as the Insurance Act, as Amended, by Adding After Section One Hundred Sixty-Four Thereof, Section One Hundred Sixty-Four-A, Making Obligatory the Insertion in the Policy of Fire Insurance a Clause on Prima Facie Evidence of Arson, and for Other Purposes"},"level":"law","status":"active","topics":["dispute"],"docNumber":"Republic Act No. 1481","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1481_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1315-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Act Numbered Two thousand four hundred and twenty-seven, otherwise known as \"The Insurance Act\" as amended, is hereby amended by adding after section one hundred and sixty-four thereof the following new section:\n\"Sec. 164-A. It shall be obligatory on the part of the insurer to insert in the policy, except in cases of insurance of residential buildings, or buildings used for purely residential purposes, the following clause:\n\" Prima facie evidence of arson. — The concurrence of at least one circumstance specified in paragraph one with any of the circumstances mentioned in paragraph two, infra, shall constitute prima facie evidence of arson:\n\"1. (a) That the fire insured against started under suspicious circumstances in the building, store or establishment owned, leased or occupied by the insured, such as that within or in the ruins of said building, store or establishment have been found within twelve hours after the said fire occurred and in the presence of a police officer or fire fighting officer investigating the fire, rags or jute sacks soaked in gasoline, kerosene, petroleum or other inflammable materials, or any mechanical or electrical contrivance calculated or designed to start a fire; or (b) That the said fire broke out in different parts of the same premises at about the same time; or (c) That during the life of the policy, more than two fires have occurred in the premises within a period of three months, with the abovementioned circumstances indicating incendiary origin; or (d) That there was stored therein gasoline, petroleum or easily inflammable material, in violation of the conditions of the policy or of an insurance policy for said building, store or establishment;\n\"2. (a) If the total amount of insurance carried on said building, merchandise, furniture or other goods insured by one or several insurance companies, exceeds seventy per cent of the value of the properties insured: or (b) when a substantial portion of the effects insured and stored therein had been withdrawn from the premises, except in the ordinary course of business, shortly before the fire; or (c) if the fire occurs within the period of three months from the date of the policy.\""}},{"id":"PH-H1315-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18"};
  FT["PH-H1316"] = {"id":"PH-H1316","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1482_1956.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"修订第 613 号共和国法（即《出口管制法》，经第 824 号与第 999 号共和国法重新颁布并修正）第 1、3、4 与 5 条","en":"An Act to Amend Sections One, Three, Four and Five of Republic Act Numbered Six Hundred Thirteen, Otherwise Known as the Export Control Law, as Re-Enacted and Amended by Republic Acts Numbered Eight Hundred Twenty-Four and Nine Hundred Ninety-Nine","orig":"An Act to Amend Sections One, Three, Four and Five of Republic Act Numbered Six Hundred Thirteen, Otherwise Known as the Export Control Law, as Re-Enacted and Amended by Republic Acts Numbered Eight Hundred Twenty-Four and Nine Hundred Ninety-Nine"},"level":"law","status":"active","topics":["trade"],"docNumber":"Republic Act No. 1482","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1482_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1316-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Six hundred thirteen as amended, otherwise known as the Export Control Law, is hereby further amended as follows:\n\"Sec. 1. In order to promote economic and industrial development and to safeguard national security, it shall be unlawful for any person, association or corporation to export, re-export or tranship, or to attempt to export, re-export or tranship to any point outside the Philippines uranium and other atomic energy materials, machineries and their spare parts, scrap metals, medicines, foodstuffs, abaca seedlings, gasoline, oil, lubricants and military equipment or supplies suitable for military use, and such other items as may be deemed essential for industrialization and economic development without a permit from the President which may be issued in accordance with the provisions of the next succeeding section: Provided, However , That all other items not otherwise specifically enumerated in this Act the exportation, re-exportation or transshipment of which is prohibited by the President in pursuance of the provisions of this Act shall be reported to both Houses of Congress which may, by joint resolution, lift the prohibition of any or all of such items herein contemplated.\""}},{"id":"PH-H1316-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section three of the same Act, as amended, is hereby amended to read as follows:\n\"Sec. 3. The President is hereby authorized to control, curtail, regulate and/or prohibit the exportation or re-exportation of such materials, goods and things referred to in the preceding section upon the recommendation of the National Economic Council and issue rules and regulations as may be necessary to carry out the provisions of this Act.\""}},{"id":"PH-H1316-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section four of Republic Act Numbered Six hundred thirteen, otherwise known as the Export Control Law, is hereby further amended to read as follows:\n\"Sec. 4. In case of violation of this Act or the regulations promulgated thereunder, such violator or violators shall, upon conviction, be punished by a fine of ten thousand pesos to twenty thousand pesos, or by imprisonment of from five to ten years, or both, in the discretion of the Court and if the violator is an alien he shall be deported after service of sentence: Provided, That if the violation is committed by the manager, representative, director, agent, or employee of any natural or juridical person in the interest of the latter the same shall render the said natural or juridical person amenable to the penalties corresponding to the particular offense: Provided, further, That in case of any violation committed in the interest of a foreign corporation legally doing business in the Philippines by its agent, manager, representative or director, such violation shall, in addition to the penalties mentioned above, serve as a ground for the immediate revocation of its license to do business: Provided, still further, That the fact that an article or articles not covered by the necessary clearance or permit are found at the port preparatory to, or in the process of, loading, whether or not concealed in or mixed with other items for export, or that there is an excess over the quantity appearing on the clearance or permit shall constitute prima facie evidence of a violation of this Act: And, Provided, finally, That the materials intended for export in violation of this Act and the rules and regulations thereunder shall be confiscated by and forfeited to the Government. Acquittal in a prosecution for violation of this Act shall not be a bar to proceedings pursuant to Articles XIX and XX of Chapter 39 of the Revised Administrative Code in separate and distinct proceedings.\""}},{"id":"PH-H1316-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section five of Republic Act Numbered Six hundred thirteen is hereby amended to read as follows:\n\"Sec. 5. The authority granted in this Act shall terminate on December thirty-one, nineteen hundred and fifty-nine unless sooner terminated by concurrent resolution of Congress, except that as to offenses committed, or rights or liabilities, incurred prior to such repeal or termination, the provisions of this Act and of the rules and regulations issued thereunder shall be treated as remaining in effect for the purpose of sustaining any suit, action, or prosecution with respect to such rights, liabilities or offense.\""}},{"id":"PH-H1316-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Sections One, Three, Four and Five of Republic Act Numbered Six Hundred Thirteen, Otherwise Known as the Export Control Law, as Re-Enacted and Amended by Republic Acts Numbered Eight Hundred Twenty-Four and Nine Hundred Ninety-Nine","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1317"] = {"id":"PH-H1317","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1483_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Amount of Sixty Thousand Pesos to Carry Out the Provisions of Republic Act Numbered Eight Hundred Forty-Two with Respect to Officials and Employees of the Bureau of Private Schools for the Fiscal Year Nineteen Hundred Fifty-Five-Nineteen Hundred Fifty-Six","orig":"An Act Appropriating the Amount of Sixty Thousand Pesos to Carry Out the Provisions of Republic Act Numbered Eight Hundred Forty-Two with Respect to Officials and Employees of the Bureau of Private Schools for the Fiscal Year Nineteen Hundred Fifty-Five-Nineteen Hundred Fifty-Six"},"level":"law","status":"active","topics":["labor","education"],"docNumber":"Republic Act No. 1483","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1483_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1317-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of sixty thousand pesos (₱60,000) or so much thereof as may be necessary is appropriated out of any unexpended balance from the collection of one per cent assessment on the gross income of private schools, colleges, and universities from tuition and other fees to carry out the provisions of Republic Act Numbered Eight hundred forty-two with respect to officials and employees of the Bureau of Private Schools."}},{"id":"PH-H1317-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect on July one, nineteen hundred and fifty-five.\nApproved: June 16, 1956."}}],"pack":"ph-p18"};
  FT["PH-H1318"] = {"id":"PH-H1318","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1484_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Seventy-Five Thousand Pesos as Aid to the Philippine Public School Teachers Association, Inc. in Sponsoring the Nineteen Hundred and Fifty-Six Delegate Conference of the World Confederation of Organizations of the Teaching Profession (Wcotp), to be Held in the City of Manila and the City of Baguio in August, Nineteen Hundred and Fifty-Six","orig":"An Act Appropriating the Sum of Seventy-Five Thousand Pesos as Aid to the Philippine Public School Teachers Association, Inc. in Sponsoring the Nineteen Hundred and Fifty-Six Delegate Conference of the World Confederation of Organizations of the Teaching Profession (Wcotp), to be Held in the City of Manila and the City of Baguio in August, Nineteen Hundred and Fifty-Six"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1484","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1484_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1318-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of seventy-five thousand pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, as aid to the Philippine Public School Teachers Association, Inc., in sponsoring the Nineteen hundred and fifty-six Delegate Conference of the World Confederation of Organizations of the Teaching Profession (WCOTP), to be held in the City of Manila and the City of Baguio in August, nineteen hundred and fifty-six."}},{"id":"PH-H1318-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The funds herein appropriated shall be disbursed by the Secretary of the Department of Education, with the approval of the President of the Philippines, subject to the established rules and regulations governing the expenditures of public funds and all unexpended balance shall revert to the general fund."}},{"id":"PH-H1318-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18"};
  FT["PH-H1319"] = {"id":"PH-H1319","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1485_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"1955年土地改革法","en":"Land Reform Act of 1955","orig":"An Act Amending Certain Sections of Republic Act Numbered Fourteen Hundred, Otherwise Known as the “Land Reform Act of 1955”"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 1485","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1485_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1319-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eleven of Republic Act Numbered Fourteen hundred is amended to read as follows:\n\"Sec. 11. Lands subject to purchase. — The Administration, acting for and on behalf of the Government, may negotiate to purchase any privately-owned agricultural land when the majority of the tenants therein or occupants thereof in case of abandoned land petition for such purchase.\""}},{"id":"PH-H1319-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section sixteen of the same Act is amended to read as follows:\n\"Sec. 16. When proper. -The Administration may initiate and prosecute expropriation proceedings for the acquisition of private agricultural land subject to the provisions of section six, paragraph (2), upon petition of a majority of the tenants or occupants thereof in case of abandoned land and after it is convinced of the suitability of such land for subdivision into family-size farm units, and that public interest will be served by its immediate acquisition, when any of the following conditions exists:\n\"(1) That the landowner falling within the terms of section six, paragraph (2), continues to refuse to sell after all efforts have been exhausted by the Administration to negotiate for its purchase; or \"(2) The landowner is willing to sell under sections eleven and twelve but cannot agree with the Administration as to the price and/or the manner of its payment.\""}},{"id":"PH-H1319-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Paragraph (3) of section twenty-three of the same Act is amended to read as follows:\n\"(3) At cost—shall mean the purchase price plus six per cent interest per annum which includes the one per cent per annum for administration expenses, plus actual expenses for survey, subdivision and registration. The cost shall be paid on the basis of a twenty-five-year amortization plan."}},{"id":"PH-H1319-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Land Reform Act of 1955","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1320"] = {"id":"PH-H1320","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1486_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1411号共和国法第\"f,\" Section 2款宿务省第17款第I组第（b）项的法案","en":"An Act Amending Item (b), Group I, Paragraph Seventeen, for the Province of Cebu, Subsection “f,” Section Two of Republic Act Numbered Fourteen Hundred Eleven","orig":"An Act Amending Item (b), Group I, Paragraph Seventeen, for the Province of Cebu, Subsection “f,” Section Two of Republic Act Numbered Fourteen Hundred Eleven"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1486","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1486_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1320-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item (b), Group I, paragraph seventeen, for the Province of Cebu, subsection \"f,\" section two of Republic Act Numbered Fourteen hundred eleven is amended to read as follows:\n\"(b) Barrio Schools to be designated by the Municipal Mayor, Danao Construction and/or repair ₱18,000.00\""}},{"id":"PH-H1320-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Item (b), Group I, Paragraph Seventeen, for the Province of Cebu, Subsection “f,” Section Two of Republic Act Numbered Fourteen Hundred Eleven","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1321"] = {"id":"PH-H1321","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1487_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第1214号与第1411号共和国法若干项目的法案","en":"An Act Amending Certain Items of Republic Acts Numbered Twelve Hundred and Fourteen Hundred Eleven","orig":"An Act Amending Certain Items of Republic Acts Numbered Twelve Hundred and Fourteen Hundred Eleven"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1487","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1487_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1321-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item one hundred two, paragraph m, section two of Republic Act Numbered Twelve hundred, is hereby amended to read as follows:\n\"(102) Construction of Home Economics Building, San Vicente (Sur) Barrio School ₱1,000.00\""}},{"id":"PH-H1321-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Items fifty-eight and sixty of paragraph m, group II, section three of Republic Act Numbered Fourteen hundred eleven, are hereby amended to read as follows:\n\"(58) San Vicente (Sur) Barrio School, Home Economics Building, Iriga Construction ₱3,000.00 \"(60) San Nicolas School Building, Completion 1,800.00\""}},{"id":"PH-H1321-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Certain Items of Republic Acts Numbered Twelve Hundred and Fourteen Hundred Eleven","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1322"] = {"id":"PH-H1322","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1488_1956.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"授予 Monserrat 运输公司在马尼拉市、奎松市与帕赛市及黎刹、布拉干、拉古纳与甲米地省建设、运营私人固定点对点及陆基无线电台的临时许可的法案","en":"An Act Granting the Monserrat Transportation, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications in the Cities of Manila, Quezon, and Pasay and in the Provinces of Rizal, Bulacan, Laguna, and Cavite","orig":"An Act Granting the Monserrat Transportation, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications in the Cities of Manila, Quezon, and Pasay and in the Provinces of Rizal, Bulacan, Laguna, and Cavite"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1488","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1488_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1322-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Monserrat Transportation, Inc., its successors or assigns, a temporary permit to construct, maintain and operate in the cities of Manila, Quezon, and Pasay and in the provinces of Rizal, Bulacan, Laguna and Cavite, private fixed point-to-point and land based and land mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephone, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1322-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places stated above, and is granted upon the express condition that the same shall be void unless the construction or installation of said stations be begun within one year from the date of the approval of this Act and be completed within two years from said date."}},{"id":"PH-H1322-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors, or assigns, shall not engage in domestic business of telecommunications in the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain, and operate private fixed point-to-point and land based and land mobile radio stations in such places within the Philippines as the interests of the grantee may justify."}},{"id":"PH-H1322-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H1322-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1322-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H1322-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, is authorized to operate its private fixed point-to-point and land based and land mobile radio stations on the medium frequency, high frequency, and very high frequency, that may be assigned to him by the Secretary of Public Works and Communications."}},{"id":"PH-H1322-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use, or possession thereof by any department of the Government upon just compensation."}},{"id":"PH-H1322-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This temporary permit shall be subject to the amendment, alteration, or repeal by the Congress of the Philippines when public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H1322-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Monserrat Transportation, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications in the Cities of Manila, Quezon, and Pasay and in the Provinces of Rizal, Bulacan, Laguna, and Cavite","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1323"] = {"id":"PH-H1323","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1489_1956.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Bartolome E. San Diego 在马尼拉市建设、运营和维护制冰厂与冷库并售冰及供应冷库的特许经营权法案","en":"An Act Granting Bartolome E. San Diego, a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the City of Manila, and to Sell Ice and to Supply Cold Storage Therein","orig":"An Act Granting Bartolome E. San Diego, a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the City of Manila, and to Sell Ice and to Supply Cold Storage Therein"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1489","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1489_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1323-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions imposed by this Act, there is hereby granted Bartolome E. San Diego, hereinafter referred to as the grantee, a franchise to construct, operate and maintain an ice plant and cold storage in the City of Manila, for the purpose of manufacturing and distributing ice and supplying cold storage therein and to charge and collect a schedule of prices and rates for the ice and cold storage so furnished, which schedule of prices and rates shall at all times be subject to regulation by the Public Service Commission or its legal successor."}},{"id":"PH-H1323-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Said grantee shall manufacture and supply ice up to the limit of the capacity of its plant, said limit to be determined by the Public Service Commission or its legal successor in such certificate of convenience and public necessity as may be issued by it as prescribed by section four of this Act."}},{"id":"PH-H1323-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe, and first class in every respect, and the grantee shall, whenever the Public Service Commission or its legal successor shall determine that public interest reasonably requires it, change or alter any of its apparatus and appurtenances at grantee’s expense."}},{"id":"PH-H1323-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not exercise any right or privilege under this franchise nor commence any construction thereunder, unless and until the grantee shall first file with the Public Service Commission within one hundred and twenty days from the date of the approval of this Act:\n(1) Its written acceptance of the terms and provisions of this Act;\n(2) Its written acceptance of the terms and conditions of the certificate of convenience and public necessity required by law for the granting of this franchise and issued by the Public Service Commission of the form and character provided for in Commonwealth Act Numbered One hundred and forty-six, as amended; and\n(3) A document or documents evidencing receipt by the Treasurer of the Philippines of the deposit or deposits required by law for each certificate of convenience and public necessity as an earnest proof of good faith and guaranty that the grantee shall complete the work within the period to be fixed by the Commission.\nIf the grantee shall not commence the manufacture and distribution of ice and the supplying of cold storage in the places referred to in the certificate of convenience and public necessity, obtained and filed as herein provided, within such period as the Public Service Commission or its legal successor shall have fixed, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee’s control, said Commission or its legal successor may in its discretion declare such certificate to be null and void, and the deposit or deposits made by the grantee forfeited in favor of the National Government."}},{"id":"PH-H1323-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"After grantee’s compliance with the requirements of the next preceding section, the Public Service Commission or its legal successor, by proper order or writ, shall authorize the construction of necessary work for the purposes of this franchise within a reasonable time to be determined by the said Commission.\nUpon determination by the Public Service Commission or its legal successor after a hearing, upon reasonable written notice to the grantee, that the grantee has violated any of the provisions of this section as to the commencement and/or completion of work authorized by the certificate of convenience and public necessity, the said Commission or its legal successor shall declare the bond or bonds forfeited as liquidated damages and not as a penalty to the National Government. The said Commission or its legal successor shall order return of the deposit as aforestated, together with any interest or dividends thereon received by the Treasurer of the Philippines, to the grantee upon the satisfactory completion of any work authorized by its certificate of convenience and public necessity, in accordance with the terms and conditions of said certificate obtained, and the Treasurer of the Philippines shall return said deposit to the grantee together with said interest and/or dividends immediately upon presentation to him of a certified copy of such order of the Public Service Commission or its legal successor."}},{"id":"PH-H1323-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This franchise is granted subject to the provisions of the Constitution and Commonwealth Act Numbered One hundred forty-six, as amended, and with the understanding and upon the condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when public interest so requires, and that it shall be subject to the pertinent provisions of Act Numbered Fourteen hundred and fifty-nine, as amended.\nThe Public Service Commission shall prescribe as a condition for the issuance of the certificate of convenience and public necessity to the grantee that the certificate shall be valid only for a definite period of time and that the violation of any of these conditions shall cause the immediate cancellation of the certificate without the necessity of any express action on the part of the Commission."}},{"id":"PH-H1323-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the city treasurer or his authorized representatives, and it shall be the duty of the grantee to submit to the city treasurer quarterly reports in duplicate showing the gross receipts for the quarter past, one of which shall be forwarded by the city treasurer to the Auditor-General, who shall keep the same on file."}},{"id":"PH-H1323-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, with the approval of the Congress of the Philippines first had, may sell, lease, grant, convey, assign, give in usufruct, or transfer this franchise and all property and rights acquired thereunder to any individual, co-partnership, private, public or quasi-public association, corporation, or joint-stock company competent to operate the business hereby authorized, but transfer of title to the franchise or any right of ownership or interest acquired under sale, lease, grant, conveyance, assignment, gift in usufruct, or transfer shall not be effective even after such approval shall have been obtained until there shall have been filed in the office of the Public Service Commission or its legal successor an agreement in writing by which the individual, co-partnership, private, public or quasi-public association, corporation, or joint-stock company in whose favor such sale, lease, grant, conveyance, assignment, gift in usufruct, or transfer is made, shall be firmly bound to comply with all the terms and conditions imposed upon the grantee by this franchise and by any and all certificates of convenience and public necessity theretofore issued by the Public Service Commission or its legal successor, and to accept the same subject to all existing terms and conditions."}},{"id":"PH-H1323-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Public Service Commission or its legal successor shall have the power, after a reasonable written notice to the grantee and a hearing of the interested parties, to declare the forfeiture of this franchise and all rights inherent in the same for failure on the part of the grantee to comply with any of the terms and conditions thereof, unless such failure shall have been directly and primarily caused by an act of God, force majeure, usurped right, uprising or other cause beyond the grantee’s control. Against such declaration of forfeiture by the Public Service Commission or its legal successor, the grantee may apply for the remedies provided in sections thirty-four and thirty-six of Commonwealth Act Numbered One hundred and forty-six, as amended. The remedy provided herein shall not be a bar to any other remedy provided by existing laws for the forfeiture of this franchise."}},{"id":"PH-H1323-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"In the event of any competing individual, association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons, or corporation."}},{"id":"PH-H1323-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Bartolome E. San Diego, a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the City of Manila, and to Sell Ice and to Supply Cold Storage Therein","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1324"] = {"id":"PH-H1324","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1490_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"宣布某些建筑材料短缺并授权菲律宾总统降低此类建筑材料关税税率的法案","en":"An Act Declaring Shortages in Certain Construction Materials and Authorizing the President of the Philippines to Reduce Tariff Rates for Such Construction Materials","orig":"An Act Declaring Shortages in Certain Construction Materials and Authorizing the President of the Philippines to Reduce Tariff Rates for Such Construction Materials"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1490","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1490_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1324-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In view of the shortage of the materials hereinafter specified, the President of the Philippines, upon prior investigation by and recommendation of the National Economic Council, which shall conduct public hearings to determine the acuteness of the shortage demanding the reduction considering public interest, is hereby authorized to reduce the present rates of tariff duty provided under existing law by not more than the corresponding percentage as follows:\n\"1. Cement 70%\n2. Steel, reinforcing and structural 75%\n3. Asphalt 100%\n4. G.I. sheets and building hardwares 75%\n5. Pipes and plumbing materials 75%\n6. Electric wires 75%"}},{"id":"PH-H1324-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The authority herein granted and the rates as reduced by the President under the authority of this Act shall terminate upon the enactment of a new tariff law."}},{"id":"PH-H1324-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring Shortages in Certain Construction Materials and Authorizing the President of the Philippines to Reduce Tariff Rates for Such Construction Materials","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
