  FT["PH-H1329"] = {"id":"PH-H1329","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1495_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Cuyo市","en":"An Act Converting the Sitio of Danawan, Municipality of Cuyo, Province of Palawan, into a Barrio of Said Municipality","orig":"An Act Converting the Sitio of Danawan, Municipality of Cuyo, Province of Palawan, into a Barrio of Said Municipality"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1495","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1495_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1329-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Danawan, Municipality of Cuyo, Province of Palawan, is converted into a barrio of said municipality to be known as the barrio of Danawan."}},{"id":"PH-H1329-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18"};
  FT["PH-H1330"] = {"id":"PH-H1330","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1496_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Puerto Princesa市","en":"An Act Creating the Barrio of San Pedro in the Municipality of Puerto Princesa, Province of Palawan","orig":"An Act Creating the Barrio of San Pedro in the Municipality of Puerto Princesa, Province of Palawan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1496","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1496_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1330-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of San Pedro, Abanico and Tiniguiban, Municipality of Puerto Princesa, Province of Palawan, are constituted into a distinct and independent barrio of said municipality to be known as the Barrio of San Pedro."}},{"id":"PH-H1330-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1956."}}],"pack":"ph-p18"};
